@classmethod
def assign_try(
        cls, moves, with_childs=True, grouping=('product',), pblc=None):
    '''
    Try to assign moves.
    It uses pblc as product by location by company if provided otherwise it
    computes based on today.
    It will split the moves to assign as much possible.
    Return True if succeed or False if not.
    '''
    pool = Pool()
    Product = pool.get('product.product')
    Uom = pool.get('product.uom')
    Date = pool.get('ir.date')
    Location = pool.get('stock.location')

    moves = [m for m in moves if m.state in {'draft', 'staging'}]
    if not moves:
        return True

    if with_childs:
        locations = Location.search([
                ('parent', 'child_of',
                    [x.from_location.id for x in moves]),
                ])
    else:
        locations = list(set((m.from_location for m in moves)))
    location_ids = [l.id for l in locations]
    product_ids = list(set((m.product.id for m in moves)))
    stock_date_end = Date.today()

    if pblc is None:
        pblc = {}
        companies = {m.company for m in moves}
        for company in companies:
            with Transaction().set_context(company=company.id):
                stock_date_end = Date.today()

            cls._assign_try_lock(
                product_ids, location_ids, [company.id],
                stock_date_end, grouping)

            with Transaction().set_context(
                    stock_date_end=stock_date_end,
                    stock_assign=True,
                    company=company.id):
                pblc[company.id] = Product.products_by_location(
                    location_ids,
                    grouping=grouping,
                    grouping_filter=(product_ids,))

    def get_key(move, location_id):
        key = [location_id]
        for field in grouping:
            value = getattr(move, field)
            if isinstance(value, Model):
                value = value.id
            key.append(value)
        return tuple(key)

    def get_values(key, location_name):
        yield location_name, key[0]
        for field, value in zip(grouping, key[1:]):
            if value is not None and '.' not in field:
                yield field, value

    def match(key, pattern):
        for k, p in zip(key, pattern):
            if p is None or k == p:
                continue
            else:
                return False
        else:
            return True

    def default_values(values):
        def get_value(name):
            def get_default(data):
                return values[data['id']].get(name, data[name])
            return get_default
        default = {}
        for name in set().union(*(v.keys() for v in values.values())):
            default[name] = get_value(name)
        return default

    child_locations = {}
    to_write = []
    to_assign = []
    to_copy = defaultdict(list)
    success = True
    for move in moves:
        if move.state != 'draft':
            if move.state == 'staging':
                success = False
            continue
        pbl = pblc[move.company.id]
        # Keep location order for pick_product
        if with_childs:
            childs = child_locations.get(move.from_location)
            if childs is None:
                childs = Location.search([
                        ('parent', 'child_of', [move.from_location.id]),
                        ('type', '!=', 'view'),
                        ])
                child_locations[move.from_location] = childs
        else:
            childs = [move.from_location]
        # Prevent picking from the destination location
        try:
            childs.remove(move.to_location)
        except ValueError:
            pass
        # Try first to pick from source location
        try:
            childs.remove(move.from_location)
            childs.insert(0, move.from_location)
        except ValueError:
            # from_location may be a view
            pass
        location_qties = []
        for key, qty in pbl.items():
            move_key = get_key(move, key[0])
            if match(key, move_key):
                qty = Uom.compute_qty(
                    move.product.default_uom, qty, move.unit,
                    round=False)
                location_qties.append((key, qty))

        location_qties = move.sort_quantities(
            location_qties, childs, grouping)
        to_pick = move.pick_product(location_qties)

        picked_qties = 0.0
        for _, qty in to_pick:
            picked_qties += qty

        if move.quantity - picked_qties >= move.unit.rounding:
            success = False
            first = False
            values = {
                'quantity': move.unit.round(
                    move.quantity - picked_qties),
                }
            to_write.extend([[move], values])
        else:
            first = True
        for key, qty in to_pick:
            values = dict(get_values(key, 'from_location'))
            values['quantity'] = move.unit.round(qty)
            if first:
                to_write.extend([[move], values])
                to_assign.append(move)
                first = False
            else:
                to_copy[move].append(values)

            qty_default_uom = Uom.compute_qty(
                move.unit, qty, move.product.default_uom, round=False)

            pbl[key] = pbl.get(key, 0.0) - qty_default_uom

    with Transaction().set_context(_stock_move_split=True):
        while to_copy:
            moves_to_copy = []
            values = {}
            for move, vlist in list(to_copy.items()):
                if vlist:
                    moves_to_copy.append(move)
                    values[move.id] = vlist.pop(0)
                else:
                    del to_copy[move]
            to_assign.extend(cls.copy(
                    moves_to_copy,
                    default=default_values(values)))
    if to_write:
        cls.write(*to_write)
    if to_assign:
        cls.assign(to_assign)
    return success

def sort_quantities(self, quantities, locations, grouping):
    """
    Return the quantities ordered by pick preference which is the locations
    order by default.
    """
    locations = {l.id: i for i, l in enumerate(locations)}
    quantities = filter(lambda x: x[0][0] in locations, quantities)
    return sorted(quantities, key=lambda x: locations[x[0][0]])

@classmethod
@without_check_access
def check_period_closed(cls, moves, state=None):
    pool = Pool()
    Period = pool.get('stock.period')

    def exclude_draft_staging(move):
        return (state if state else move.state) not in {'draft', 'staging'}

    for company, moves in groupby(
            filter(exclude_draft_staging, moves), lambda m: m.company):
        periods = Period.search([
                ('state', '=', 'closed'),
                ('company', '=', company.id),
                ], order=[('date', 'DESC')], limit=1)
        if periods:
            period, = periods
            for move in moves:
                date = (move.effective_date if move.effective_date
                    else move.planned_date)
                if date and date <= period.date:
                    raise AccessError(
                        gettext('stock.msg_move_modify_period_close',
                            move=move.rec_name,
                            period=period.rec_name))

@classmethod
def check_modification(cls, mode, moves, values=None, external=False):
    super().check_modification(
        mode, moves, values=values, external=external)
    if mode == 'create':
        cls.check_period_closed(moves)
    elif mode == 'write':
        if values.keys() - cls._allow_modify_closed_period:
            cls.check_period_closed(moves, state=values.get('state'))
        if values.keys() & cls._deny_modify_assigned:
            for move in moves:
                if move.state == 'assigned':
                    raise AccessError(gettext(
                            'stock.msg_move_modify_assigned',
                            move=move.rec_name))
        if values.keys() & cls._deny_modify_done_cancel:
            for move in moves:
                if move.state in {'done', 'cancelled'}:
                    raise AccessError(gettext(
                            'stock.msg_move_modify_%s' % move.state,
                            move=move.rec_name))
    elif mode == 'delete':
        for move in moves:
            if (move.state not in {'staging', 'draft', 'cancelled'}
                    and move.quantity):
                raise AccessError(gettext(
                        'stock.msg_move_delete_draft_cancel',
                        move=move.rec_name))

def _location_children(location_ids, query=False):
    "Return children location without including flat children"
    pool = Pool()
    Location = pool.get('stock.location')
    nested_location_ids = []
    flat_location_ids = []
    for location in Location.browse(location_ids):
        if location.flat_childs:
            flat_location_ids.append(location.id)
        else:
            nested_location_ids.append(location.id)
    if nested_location_ids:
        return Location.search(['OR',
                [
                    ('parent', 'child_of', nested_location_ids),
                    ('parent.flat_childs', '!=', True),
                    ],
                ('id', 'in', location_ids),
                ], query=query, order=[])
    else:
        if query:
            return flat_location_ids
        else:
            return Location.browse(flat_location_ids)

@classmethod
def products_by_location(cls, location_ids,
        with_childs=False, grouping=('product',), grouping_filter=None):
    """
    Compute for each location and product the stock quantity in the default
    uom of the product.

    The context with keys:
        stock_skip_warehouse: if set, quantities on a warehouse are no more
            quantities of all child locations but quantities of the storage
            zone.

    Return a dictionary with location id and grouping as key
            and quantity as value.
    """
    pool = Pool()
    Location = pool.get('stock.location')
    Move = pool.get('stock.move')

    # Skip warehouse location in favor of their storage location
    # to compute quantities. Keep track of which ids to remove
    # and to add after the query.
    storage_to_remove = set()
    wh_to_add = {}
    if Transaction().context.get('stock_skip_warehouse'):
        location_ids = set(location_ids)
        for location in Location.browse(list(location_ids)):
            if location.type == 'warehouse':
                location_ids.remove(location.id)
                if location.storage_location.id not in location_ids:
                    storage_to_remove.add(location.storage_location.id)
                location_ids.add(location.storage_location.id)
                wh_to_add[location.id] = location.storage_location.id
        location_ids = list(location_ids)

    query = Move.compute_quantities_query(location_ids, with_childs,
        grouping=grouping, grouping_filter=grouping_filter)
    if query is None:
        return {}
    quantities = Move.compute_quantities(query, location_ids, with_childs,
        grouping=grouping, grouping_filter=grouping_filter)

    if wh_to_add:
        for wh, storage in wh_to_add.items():
            for key in list(quantities.keys()):
                if key[0] == storage:
                    quantities[(wh,) + key[1:]] = quantities[key]
                    if storage in storage_to_remove:
                        del quantities[key]
    return quantities

@staticmethod
def transition(state):
    def check_transition(func):
        @wraps(func)
        def wrapper(cls, records, *args, **kwargs):
            filtered = []
            to_update = OrderedDict()

            assert len(records) == len(set(records)), "Duplicate records"

            for record in records:
                current_state = getattr(record, cls._transition_state)
                transition = (current_state, state)
                if transition in cls._transitions:
                    filtered.append(record)
                    if current_state != state:
                        to_update[record] = current_state

            result = func(cls, filtered, *args, **kwargs)
            if to_update:
                for record in list(to_update.keys()):
                    current_state = getattr(record, cls._transition_state)
                    if current_state != to_update[record]:
                        del to_update[record]
                to_update = list(to_update)
                cls.write(to_update, {
                        cls._transition_state: state,
                        })
                cls.log(
                    to_update, 'transition',
                    f'{cls._transition_state}:{state}')
            return result
        return wrapper
    return check_transition

@classmethod
@no_table_query
def create(cls, vlist):
    transaction = Transaction()
    cursor = transaction.connection.cursor(row_factory=backend.scalar_row)
    pool = Pool()
    Translation = pool.get('ir.translation')

    vlist_orig = vlist
    vlist = cls._before_create(vlist)

    table = cls.__table__()
    modified_fields = set()
    defaults_cache = {}  # Store already computed default values
    missing_defaults = {}  # Store missing default values by schema
    new_ids = []

    def db_insert(columns, vlist, column_names):
        if transaction.database.has_multirow_insert():
            vlist = (
                s for s in grouped_slice(
                    vlist,
                    backend.MAX_QUERY_PARAMS // (len(columns) + 1)))
        else:
            vlist = ([v] for v in vlist)

        for values in vlist:
            values = list(values)
            cols = list(columns)
            try:
                if len(values) > 1:
                    ids = transaction.database.nextid(
                        transaction.connection, cls._table,
                        count=len(values))
                    if ids is not None:
                        assert len(ids) == len(values)
                        cols.append(table.id)
                        for val, id in zip(values, ids):
                            val.append(id)
                        cursor.execute(*table.insert(cols, values))
                        yield from ids
                        continue
                for i, val in enumerate(values):
                    if transaction.database.has_returning():
                        cursor.execute(*table.insert(
                                cols, [val], [table.id]))
                        yield from cursor
                    else:
                        id_new = transaction.database.nextid(
                            transaction.connection, cls._table)
                        if id_new:
                            if i == 0:
                                cols.append(table.id)
                            val.append(id_new)
                            cursor.execute(*table.insert(cols, [val]))
                        else:
                            cursor.execute(*table.insert(cols, [val]))
                            id_new = transaction.database.lastid(cursor)
                        yield id_new
            except (
                    backend.DatabaseIntegrityError,
                    backend.DatabaseDataError
                    ) as exception:
                if isinstance(exception, backend.DatabaseIntegrityError):
                    raise_func = cls.__raise_integrity_error
                elif isinstance(exception, backend.DatabaseDataError):
                    raise_func = cls.__raise_data_error
                with transaction.new_transaction():
                    for value in values:
                        skip = len(['create_uid', 'create_date'])
                        recomposed = dict(zip(column_names, value[skip:]))
                        raise_func(
                            exception, recomposed, transaction=transaction)
                    raise

    to_insert = []
    previous_columns = [table.create_uid, table.create_date]
    previous_column_names = []

    for values in vlist:
        # Clean values
        for key in ('create_uid', 'create_date',
                'write_uid', 'write_date', 'id'):
            if key in values:
                del values[key]
        modified_fields |= values.keys()

        # Get default values
        values_schema = tuple(sorted(values))
        if values_schema not in missing_defaults:
            default = []
            missing_defaults[values_schema] = default_values = {}
            for fname, field in cls._fields.items():
                if fname in values:
                    continue
                if fname in [
                        'create_uid', 'create_date',
                        'write_uid', 'write_date', 'id']:
                    continue
                if isinstance(field, fields.Function) and not field.setter:
                    continue
                if fname in defaults_cache:
                    default_values[fname] = defaults_cache[fname]
                else:
                    default.append(fname)

            if default:
                defaults = cls.default_get(default, with_rec_name=False)
                default_values.update(cls._clean_defaults(defaults))
                defaults_cache.update(default_values)
        values.update(missing_defaults[values_schema])

        current_column_names = []
        current_columns = [table.create_uid, table.create_date]
        current_values = [transaction.user, CurrentTimestamp()]

        # Insert record
        for fname, value in sorted(values.items()):
            field = cls._fields[fname]
            if not hasattr(field, 'set'):
                current_columns.append(Column(table, fname))
                current_values.append(field.sql_format(value))
                current_column_names.append(fname)

        if current_column_names != previous_column_names:
            if to_insert:
                new_ids.extend(db_insert(
                        previous_columns, to_insert,
                        previous_column_names))
                to_insert.clear()
            previous_columns = current_columns
            previous_column_names = current_column_names
        to_insert.append(current_values)
    else:
        if to_insert:
            new_ids.extend(db_insert(
                    current_columns, to_insert, current_column_names))

    # Update path before fields_to_set which could create children
    if cls._path_fields:
        field_names = list(sorted(cls._path_fields))
        cls._set_path(field_names, repeat(new_ids, len(field_names)))
    # Update mptt before fields_to_set which could create children
    if cls._mptt_fields:
        field_names = list(sorted(cls._mptt_fields))
        cls._update_mptt(field_names, repeat(new_ids, len(field_names)))

    translation_values = {}
    fields_to_set = {}
    for values, new_id in zip(vlist, new_ids):
        for fname, value in values.items():
            field = cls._fields[fname]
            if (getattr(field, 'translate', False)
                    and not hasattr(field, 'set')):
                translation_values.setdefault(
                    '%s,%s' % (cls.__name__, fname), {})[new_id] = (
                        field.sql_format(value))
            if hasattr(field, 'set'):
                args = fields_to_set.setdefault(fname, [])
                actions = iter(args)
                for ids, val in zip(actions, actions):
                    if val == value:
                        ids.append(new_id)
                        break
                else:
                    args.extend(([new_id], value))

    if translation_values:
        for name, translations in translation_values.items():
            Translation.set_ids(name, 'model', Transaction().language,
                list(translations.keys()), list(translations.values()))

    for fname in sorted(fields_to_set, key=cls.index_set_field):
        fargs = fields_to_set[fname]
        field = cls._fields[fname]
        field.set(cls, fname, *fargs)

    cls._insert_history(new_ids)

    cls.__check_domain_rule(new_ids, 'create')
    return cls.browse(cls._after_create(new_ids, vlist_orig))

@dualmethod
def lock(cls, records=None):
    transaction = Transaction()
    if records is not None:
        if isinstance(records, BrowseList):
            record_ids = set(records.ids)
        else:
            record_ids = set(map(int, records))
        new_ids = set(transaction.create_records[cls.__name__])
        ids = record_ids - new_ids
        transaction.lock_records(cls._table, ids)
    else:
        transaction.lock_table(cls._table)
